import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test("documents cannot be added to a vendor under review", { tag: "@DOC-06" }, async ({ apiAs }) => {
    // Arrange: a draft vendor owned by the member, with every required document uploaded, then submitted into review.
    const member = await apiAs("member");
    const createRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Doc Lock Vendor"),
        category: "software",
        contact_email: `doc-lock-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
      },
    });
    expect(createRes.status(), await createRes.text()).toBe(201);
    const vendor = await createRes.json();
    expect(vendor.status).toBe("draft");

    const requiredKinds = ["w9", "insurance_certificate", "contract"] as const;
    const sampleFiles: Record<(typeof requiredKinds)[number], string> = {
      w9: "w9.txt",
      insurance_certificate: "w9.txt",
      contract: "w9.txt",
    };
    for (const kind of requiredKinds) {
      const uploadSetupRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind,
          file: {
            name: sampleFiles[kind],
            mimeType: "text/plain",
            buffer: fs.readFileSync(sample(sampleFiles[kind])),
          },
        },
      });
      expect(uploadSetupRes.status(), await uploadSetupRes.text()).toBe(201);
    }

    const submitRes = await member.post(`/api/vendors/${vendor.id}/submit`);
    expect(submitRes.status(), await submitRes.text()).toBe(200);

    await expect
      .poll(async () => {
        const res = await member.get(`/api/vendors/${vendor.id}`);
        return (await res.json()).status;
      }, { message: "vendor should reach in_review after submit" })
      .toBe("in_review");

    // Act: attempt to upload a W-9 while the vendor is under review.
    const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "w9.txt",
          mimeType: "text/plain",
          buffer: fs.readFileSync(sample("w9.txt")),
        },
      },
    });

    // Assert: refused with 409 and the vendor_locked error code.
    const body = await uploadRes.text();
    expect(uploadRes.status(), body).toBe(409);
    expect(JSON.parse(body).error.code, body).toBe("vendor_locked");
  });
});
